import type { CalculationMethod, ComponentType } from '@/features/payroll/types';

/**
 * Payroll seed for the development mock.
 *
 * Components only. Salary structures are generated by `devApi` from the live
 * teacher and staff rosters — a structure hard-coded against an employee id
 * would break the moment a roster moved, and payroll's whole point is that
 * the people it pays are the people the school already employs.
 *
 * The catalogue is deliberately mixed: percentage and fixed allowances, one
 * that counts toward PF wages and several that do not, an optional deduction,
 * a statutory one the module writes itself, and a retired component — so
 * every branch of the component form and the PF-wages rule is reachable
 * without editing anything.
 */

export interface ComponentSeed {
  id: number;
  name: string;
  code: string;
  type: ComponentType;
  calculation: CalculationMethod;
  value: number;
  isStatutory?: boolean;
  isTaxable?: boolean;
  /** Whether this allowance enters the wage PF is charged on. */
  affectsPf?: boolean;
  isActive?: boolean;
  sortOrder: number;
}

