/**
 * Basic salaries by designation band, in rupees.
 *
 * The patterns match the designations the **teacher and staff seeds actually
 * use** — `Housekeeping Attendant`, `Bus Driver`, `Head of Department` — not
 * the job titles one might guess. A band that matches nothing silently drops
 * everybody to the default, which is how a whole statutory scheme ends up
 * with no members to show.
 *
 * The figures straddle both ceilings on purpose. With the seeded allowances
 * (20% DA + 40% HRA + 10% special, plus ₹2,850 fixed) a gross lands inside
 * the ₹21,000 ESI ceiling only up to a basic of about ₹10,600 — so the two
 * lowest bands attract ESI and nobody else does, which is exactly who the
 * scheme covers. PF wages are basic plus DA, so every band above ₹12,500 is
 * capped at the PF ceiling and the top band contributes on the full wage.
 *
 * First match wins, so the most specific patterns come first.
 */
export const BASIC_BANDS: { match: RegExp; basic: number }[] = [
  { match: /principal|head of department/i, basic: 62_000 },
  { match: /senior|coordinator|counsellor|vice/i, basic: 41_000 },
  { match: /teacher|coach|lecturer/i, basic: 24_000 },
  { match: /accounts|librarian|front desk/i, basic: 17_000 },
  // Inside the ESI ceiling, just — the boundary worth exercising.
  { match: /driver|security/i, basic: 10_200 },
  { match: /attendant|housekeeping|peon|cleaner|helper/i, basic: 9_500 },
];

/** What a designation falls back to when nothing matches. */
export const DEFAULT_BASIC = 15_000;

export const nextComponentId = componentSeed.length + 1;
